// m=ます形, ba=うけみ形, g=group, ex=メモ(任意)
// 語彙 = 教科書L19-3掲載語（練習1の表＋ぶんけい表＋応用）＋うけみが自然な既習語のみ
//   ※かのう形と違い「全既習語」にしない: あるきます→歩かれます 等、うけみが不自然な語が多いため。
//   追加した既習語: いいます/とります/すてます/せつめいします/でんわします
// 教科書L19-3「ぶんけい」の変換表が正（p103）: 1G=い段→あ段+れます / 2G=+られます / 3G=します→されます・きます→こられます
const VERBS=[
  // 1グループ（い段→あ段＋れます）
  {m:"ききます",ba:"きかれます",g:1},
  {m:"かきます",ba:"かかれます",g:1},
  {m:"よびます",ba:"よばれます",g:1},
  {m:"たのみます",ba:"たのまれます",g:1},
  {m:"さそいます",ba:"さそわれます",g:1,ex:"い→わ"},
  {m:"つかいます",ba:"つかわれます",g:1,ex:"い→わ"},
  {m:"いいます",ba:"いわれます",g:1,ex:"い→わ"},
  {m:"えらびます",ba:"えらばれます",g:1},
  {m:"とります",ba:"とられます",g:1,ex:"さいふを とられました"},
  // 2グループ（＋られます）
  {m:"みます",ba:"みられます",g:2,ex:"かのう<ruby>形<rt>けい</rt></ruby>と おなじ かたち"},
  {m:"おしえます",ba:"おしえられます",g:2},
  {m:"ほめます",ba:"ほめられます",g:2},
  {m:"たすけます",ba:"たすけられます",g:2},
  {m:"すてます",ba:"すてられます",g:2},
  // 3グループ（します→されます・きます→こられます）
  {m:"します",ba:"されます",g:3,ex:"×しられます"},
  {m:"しつもんします",ba:"しつもんされます",g:3},
  {m:"しょうたいします",ba:"しょうたいされます",g:3},
  {m:"せつめいします",ba:"せつめいされます",g:3},
  {m:"でんわします",ba:"でんわされます",g:3},
  {m:"コピーします",ba:"コピーされます",g:3},
  {m:"（学校へ）きます",ba:"こられます",g:3,ex:"くる→こられます・かのう<ruby>形<rt>けい</rt></ruby>と おなじ かたち"}

slots.SLOT12:
let rPool=[], rIdx=0, rState=0; // 0=ます表示, 1=うけみ形表示
const rcard=document.getElementById('rcard'), rsub=document.getElementById('rsub'), rcount=document.getElementById('rcount');
function rStart(){rPool=rshuffle(VERBS);rIdx=0;rState=0;rRender();}
function rRender(){
  const v=rPool[rIdx];
  if(rState===0){rcard.innerHTML='<span>'+v.m+' <span style="color:var(--accent);">→</span> ？</span>';rsub.textContent='（クリック）';}
  else{rcard.innerHTML='<span>'+v.m+'</span><div class="arrow">▼</div><span class="rta">'+v.ba+'</span>';rsub.innerHTML='<span class="gl gl'+v.g+'" style="padding:2px 12px;border-radius:20px;color:#fff;">'+GNAME[v.g]+'</span>　つぎへ →';}
